struct order { long id; long customer_id; };   /* object reference -> key column */

static void save_order(sqlite3 *db, const struct order *o) {
  sqlite3_stmt *st;
  sqlite3_prepare_v2(db, "UPDATE orders SET customer_id=? WHERE id=?", -1, &st, NULL);
  sqlite3_bind_int64(st, 1, o->customer_id);    /* write the other object's key */
  sqlite3_bind_int64(st, 2, o->id);
  sqlite3_step(st); sqlite3_finalize(st);
}
